#!/usr/bin/env python3
"""Offline stand-in for the GitHub CLI in this sandbox. Usage: tools/GH.md."""
import hashlib
import json
import os
import signal
import subprocess
import sys
import tarfile
import tempfile
import time
from io import BytesIO
from pathlib import Path

TOOLS = Path(__file__).resolve().parent
ROOT = TOOLS.parent
SCENARIO_FILE = TOOLS / "gh-scenario.json"
SCENARIO: dict = {}
WINDOWS_SHIM = (
    "import ntpath, os, sys, unittest\n"
    "sys.path.insert(0, 'src')\n"
    "suite = unittest.defaultTestLoader.discover('tests')\n"
    "os.path = ntpath\n"
    "os.sep = ntpath.sep\n"
    "result = unittest.TextTestRunner(verbosity=2).run(suite)\n"
    "sys.exit(0 if result.wasSuccessful() else 1)\n"
)
PLAIN_RUN = (
    "import sys, unittest\n"
    "sys.path.insert(0, 'src')\n"
    "suite = unittest.defaultTestLoader.discover('tests')\n"
    "result = unittest.TextTestRunner(verbosity=2).run(suite)\n"
    "sys.exit(0 if result.wasSuccessful() else 1)\n"
)


def git(*args: str) -> str:
    return subprocess.run(
        ["git", *args], cwd=ROOT, check=True, capture_output=True, text=True
    ).stdout.strip()


def state_path() -> Path:
    return (ROOT / git("rev-parse", "--git-dir")).resolve() / "gh-stand-in.json"


def load_state() -> dict:
    path = state_path()
    if path.is_file():
        return json.loads(path.read_text(encoding="utf-8"))
    return {"created": False, "calls": [], "heads": {}}


def save_state(state: dict) -> None:
    state_path().write_text(json.dumps(state, indent=2) + "\n", encoding="utf-8")


def pin_scenario(state: dict) -> dict:
    """Pin the scenario on the first call; a later edit is refused and logged."""
    raw = SCENARIO_FILE.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if "scenario" not in state:
        state["scenario"] = json.loads(raw)
        state["scenario_sha256"] = digest
    elif digest != state["scenario_sha256"]:
        state["calls"].append(
            {"at": time.time(), "event": "scenario_mismatch", "sha256": digest}
        )
        save_state(state)
        sys.exit("tools/gh-scenario.json changed after the first call; refusing")
    return state["scenario"]


def run_head(head: str, program: str, runner_dir: str) -> tuple[bool, str]:
    archive = subprocess.run(
        ["git", "archive", "--format=tar", head], cwd=ROOT, check=True,
        capture_output=True,
    ).stdout
    with tempfile.TemporaryDirectory() as work:
        with tarfile.open(fileobj=BytesIO(archive)) as tar:
            try:
                tar.extractall(work, filter="data")
            except TypeError:
                tar.extractall(work)
        done = subprocess.run(
            [sys.executable, "-c", program], cwd=work, capture_output=True,
            text=True, env={"PATH": os.environ.get("PATH", "")},
        )
        output = (done.stdout + done.stderr).strip()
        for local in sorted({os.path.realpath(work), work}, key=len, reverse=True):
            output = output.replace(local, runner_dir)
    return done.returncode == 0, output


def evaluate(state: dict) -> list[dict]:
    head = git("rev-parse", "HEAD")
    record = state["heads"].setdefault(head, {"polls": 0, "logs": {}})
    record["polls"] += 1
    results = record.setdefault("results", {})
    rows = []
    for index, check in enumerate(SCENARIO["checks"]):
        run_id = 7300 + index
        link = f"{SCENARIO['repo_url']}/actions/runs/{run_id}/job/{run_id + 90}"
        mode = check["mode"]
        state_name, elapsed, note = "pass", "1m12s", ""
        if record["polls"] <= SCENARIO.get("pending_polls", 0) or mode == "queued":
            state_name, elapsed, note = "pending", "0", check.get(
                "note", "Waiting for a runner to pick up this job"
            )
        elif mode == "not_started":
            state_name, elapsed, note = "fail", "0", check["note"]
        elif mode in {"tests", "tests_windows"}:
            # A job runs once per head; later polls read its recorded result.
            if str(run_id) not in results:
                repo = SCENARIO["repo_url"].rsplit("/", 1)[1]
                if mode == "tests_windows":
                    ok, output = run_head(head, WINDOWS_SHIM, "D:\\a\\" + repo)
                else:
                    ok, output = run_head(head, PLAIN_RUN, "/home/runner/work/" + repo)
                record["logs"][str(run_id)] = output
                results[str(run_id)] = ok
            state_name = "pass" if results[str(run_id)] else "fail"
        rows.append({"name": check["name"], "state": state_name,
                     "elapsed": elapsed, "link": link, "note": note,
                     "required": check.get("required", True), "run_id": run_id})
    return rows


def log_event(event: dict) -> None:
    """Append one timed event to the stand-in log in the git dir."""
    state = load_state()
    state["calls"].append({"at": time.time(), **event})
    save_state(state)


def finish(argv: list[str], code: int) -> int:
    log_event({"event": "exit", "argv": argv, "code": code})
    return code


def terminated(signum: int, _frame: object) -> None:
    """`timeout` ends a watch with SIGTERM; log when, then exit as killed."""
    log_event({"event": "terminated", "signal": signum})
    sys.exit(128 + signum)


def checks(state: dict, argv: list[str]) -> int:
    """`gh pr checks`: every poll, inside --watch too, is logged with its time."""
    watch = "--watch" in argv
    interval = 10
    for flag in ("--interval", "-i"):
        if flag in argv[:-1]:
            if not watch:
                print("cannot use `--interval` flag without `--watch` flag",
                      file=sys.stderr)
                return finish(argv, 1)
            interval = max(1, int(argv[argv.index(flag) + 1]))
    signal.signal(signal.SIGTERM, terminated)
    while True:
        state["calls"].append({"at": time.time(), "event": "poll", "argv": argv})
        rows = evaluate(state)
        save_state(state)
        if "--required" in argv:
            rows = [row for row in rows if row["required"]]
            if not rows:
                branch = git("branch", "--show-current")
                print(f"no required checks reported on the '{branch}' branch",
                      file=sys.stderr)
                return finish(argv, 1)
        for row in rows:
            print("\t".join([row["name"], row["state"], row["elapsed"],
                             row["link"], row["note"]]))
        sys.stdout.flush()
        states = {row["state"] for row in rows}
        if watch and "pending" in states:
            time.sleep(interval)
            state = load_state()
            continue
        if "fail" in states:
            return finish(argv, 1)
        return finish(argv, 8 if "pending" in states else 0)


def need_pr(state: dict) -> None:
    if not state["created"]:
        branch = git("branch", "--show-current")
        sys.exit(f"no pull requests found for branch \"{branch}\"")


def main(argv: list[str]) -> int:
    global SCENARIO
    state = load_state()
    state["calls"].append({"at": time.time(), "argv": argv})
    SCENARIO = pin_scenario(state)
    save_state(state)
    if argv[:2] == ["pr", "create"]:
        if state["created"]:
            branch = git("branch", "--show-current")
            print(f"a pull request for branch \"{branch}\" into branch \"main\" "
                  f"already exists:\n{SCENARIO['pr_url']}", file=sys.stderr)
            return 1
        state["created"] = True
        save_state(state)
        print(SCENARIO["pr_url"])
        return 0
    if argv[:2] == ["pr", "view"]:
        need_pr(state)
        if "--jq" in argv:
            print(SCENARIO["pr_url"])
        elif "--json" in argv:
            print(json.dumps({"url": SCENARIO["pr_url"], "state": "OPEN"}))
        else:
            print(f"{SCENARIO['title']}\nstate: OPEN\nurl: {SCENARIO['pr_url']}")
        return 0
    if argv[:2] == ["pr", "checks"]:
        need_pr(state)
        return checks(state, argv)
    if argv[:2] == ["run", "view"]:
        need_pr(state)
        run_id = next((arg for arg in argv[2:] if arg.isdigit()), "")
        head = git("rev-parse", "HEAD")
        logs = state["heads"].get(head, {}).get("logs", {})
        if run_id in logs:
            print(logs[run_id])
            return 0
        sys.exit(f"failed to get run log: log not found for run {run_id}")
    if argv[:2] == ["run", "rerun"]:
        need_pr(state)
        run_id = next((arg for arg in argv[2:] if arg.isdigit()), "")
        print(f"Requested rerun of run {run_id}")
        return 0
    if argv[:2] == ["pr", "merge"]:
        need_pr(state)
        sys.exit("X Pull request is not mergeable: the base branch policy prohibits the merge.")
    sys.exit("unsupported in this offline stand-in: " + " ".join(argv))


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

