// Runs in <head> before the stylesheet: applies the stored display choice so
// the first paint is already in the reader's skin and mode.
(function () {
  var stored = {};
  try { stored = JSON.parse(localStorage.getItem("display") || "{}"); } catch (e) {}
  var mode = stored.mode || "system";
  if (mode === "system") mode = matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  var root = document.documentElement;
  root.dataset.theme = mode;
  root.dataset.skin = stored.skin || "graphite";
  root.style.setProperty("--ui-scale", String((stored.size || 100) / 100));
})();

